script = '''python3 - <<'PY'
T=[[5,10,12,13,14,18,19,21,23,26],[0,2,7,10,14,15,20],[9,12,17,22,25,28],[6,9,12,13,15,18,19,20,22,23,25,26,28],[1,3,5,7,13,15],[6,7,10,11,14,15,16,17,19,20,24,27],[1,3,11,12,13,16,19,20,22,25,28]]
B=[[7,12,14,15,16,20,21,23,25],[0,2,4,9,12,16,17,22],[11,14,19,24],[8,11,14,15,17,20,21,22,24,25],[1,3,5,7,9,15,17],[8,9,12,13,16,17,18,19,21,22],[1,3,5,13,14,15,18,21,22,24]]
T={(r,c) for r,row in enumerate(T) for c in row}; B={(r,c) for r,row in enumerate(B) for c in row}
# transform top coordinates to lower coordinates: row mapping normal or vertically reflected; col mapping c+dx or 28-c+dx
results=[]
for rf in [False,True]:
 for hf in [False,True]:
  for dx in range(-29,30):
   X={(6-r if rf else r, (28-c if hf else c)+dx) for r,c in T}
   # Note X top expressed in bottom local coordinates; union cost includes clipped/outside as true mismatch.
   overlap=len(X&B); dist=len(X^B)
   # in-bounds-only misses and extras as well
   clamped={p for p in X if 0<=p[1]<29}
   visdist=len(clamped^B)+len(X-clamped)
   results.append((dist,-overlap,rf,hf,dx,visdist,len(X),len(B)))
for x in sorted(results)[:15]: print(x)
# show shift +2, no reflection coordinate diffs
for rf,hf,dx in [(False,False,2),(False,False,1),(False,False,0),(False,True,0),(True,False,2),(True,True,0)]:
 X={(6-r if rf else r,(28-c if hf else c)+dx) for r,c in T}
 dif=sorted(X^B)
 print('case',rf,hf,dx,'dist',len(dif),'mismatches',dif)
PY'''
r=terminal(script,timeout=60); print(r.get('output',''))

